import os,glob,re,json
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); print(sorted(G)); gi=G['Demo pair 1 input']; go=G['Demo pair 1 output']

from collections import Counter
def stats(g):
    cnt=Counter(x for r in g for x in r)
    h,w=len(g),len(g[0])
    # find rects: connected components of non-bg colors (bg = most common)
    bg=cnt.most_common(1)[0][0]
    seen=[[False]*w for _ in range(h)]
    comps=[]
    for i in range(h):
        for j in range(w):
            if gi[i][j]!=bg and not seen[i][j]:
                col=gi[i][j]; stack=[(i,j)]; cells=[]
                while stack:
                    a,b=stack.pop(); cells.append((a,b))
                    for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                        na,nb=a+da,b+db
                        if 0<=na<h and 0<=nb<w and not seen[na][nb] and gi[na][nb]==col:
                            seen[na][nb]=True; stack.append((na,nb))
                seen[i][j]=True
                rs=[c[0] for c in cells]; cs=[c[1] for c in cells]
                comps.append((col,len(cells),min(rs),max(rs),min(cs),max(cs)))
    return bg,comps
